fields.InputDefinition:
{
  "goal": "Do the shared setup ONCE: you are already logged in at http://localhost:4200 — navigate to the Home landing page using the Home icon/logo or the application switcher dropdown next to the logo. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) add-pin-panel-opens — in the 'Pinned' section click 'Add Pin' (thumbtack/plus icon) and confirm a slide-in panel titled 'Add Pin' appears with a search box, an 'Add to group' selector, and one or more collapsible accordion sections (Applications, Dashboards, Views, Queries, Quick Actions) with pinnable items; (2) add-pin-search-filters — type a short query into the panel's search box and confirm the accordion sections respond (items narrow to name matches, or non-matching sections disappear, or a clear empty result appears), then clear the search and confirm the fuller list returns; (3) pin-resource-roundtrip — expand 'Applications' and click 'Pin' on any application nav item and confirm a success toast ('\"...\" pinned to Home') appears AND the item's button flips to a 'Pinned' badge, then close the panel and confirm the newly pinned item appears as a card in the Home 'Pinned' grid; (4) pin-edit-mode — click the 'Edit' (pencil) button in the Pinned section header and confirm edit mode engages (an edit-mode banner, per-pin drag handles and remove (x) controls, and an 'Add Pin' placeholder card), then click 'Done' and confirm edit mode exits; (5) pin-new-group — open 'Add Pin' again, in the 'Add to group' selector choose '+ New group...' and confirm a text input appears, type a group name (e.g. 'Test Group'), then expand 'Applications' and click 'Pin' on any item, close the panel, and confirm the Pinned section renders a group header labeled with your group name (with a pin count) and the card grouped beneath it; (6) configure-action-pin — open 'Add Pin' again and look for a 'Quick Actions' section; if present, expand it and click the 'Configure' (sliders icon) button on any action item and confirm an action-pin configuration dialog opens (you do NOT need to complete it) — if there is no Quick Actions section because no actions are available, the panel rendering cleanly without that section is an acceptable pass. Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 90,
  "checkpoints": [
    {
      "name": "add-pin-panel-opens",
      "instruction": "Add Pin panel opens with resource catalog",
      "visualCriteria": [
        "The 'Add Pin' slide-in panel opens with a search box and an 'Add to group' selector, and at least one resource accordion section (e.g. Applications, Dashboards, Views, Queries, Quick Actions) renders with pinnable items or a 'Pin'/'Configure' button"
      ]
    },
    {
      "name": "add-pin-search-filters",
      "instruction": "panel search filters the catalog",
      "visualCriteria": [
        "Typing in the Add Pin panel search box narrows the catalog items to name matches (or collapses non-matching sections / shows an empty result), and clearing the search restores a broader list of pinnable items"
      ]
    },
    {
      "name": "pin-resource-roundtrip",
      "instruction": "pin an app and see it in the Pinned grid",
      "visualCriteria": [
        "Clicking 'Pin' on a catalog item produces a success toast and the item shows a 'Pinned' badge in the panel, and after closing the panel the pinned item is visible as a card in the Home 'Pinned' section"
      ]
    },
    {
      "name": "pin-edit-mode",
      "instruction": "toggle Pinned edit mode on and off",
      "visualCriteria": [
        "Clicking 'Edit' shows the edit-mode banner and reveals per-pin drag handles / remove controls and an 'Add Pin' card, and clicking 'Done' exits edit mode so the banner and edit controls disappear"
      ]
    },
    {
      "name": "pin-new-group",
      "instruction": "pin into a newly-named group",
      "visualCriteria": [
        "Selecting '+ New group...' in the group selector reveals a new-group name input, and after pinning an item into the named group the Pinned section shows a group header with that name and the item grouped under it"
      ]
    },
    {
      "name": "configure-action-pin",
      "instruction": "action-pin configure dialog or valid empty case",
      "visualCriteria": [
        "If a 'Quick Actions' section is present, clicking 'Configure' on an action opens the action-pin configuration dialog; if no actions are available, the Add Pin panel still renders correctly without a Quick Actions section (valid empty case)"
      ]
    }
  ]
}
